(function(){function m(a){var h=a.getAttribute("href");if(!h)return;try{var u=new URL(h,document.baseURI);if((u.protocol==="http:"||u.protocol==="https:")&&u.host!==location.host){a.target="_blank";a.rel="noopener noreferrer";}}catch(e){}}function s(){document.querySelectorAll("a[href]").forEach(m);}if(document.readyState!=="loading"){s();}else{document.addEventListener("DOMContentLoaded",s);}document.addEventListener("click",function(e){var a=e.target&&e.target.closest&&e.target.closest("a[href]");if(a){m(a);}},true);})();


/* TypeFlow V1 mobile keyboard bridge — preserves the original UI and logic. */
(function () {
  const input = document.getElementById("typeflow-mobile-input");
  if (!input) return;

  const isTouchDevice =
    ("ontouchstart" in window) ||
    (navigator.maxTouchPoints && navigator.maxTouchPoints > 0);

  if (!isTouchDevice) return;

  let composing = false;

  function focusNativeKeyboard() {
    try {
      input.focus({ preventScroll: true });
    } catch (_) {
      input.focus();
    }
  }

  function forwardKey(key, code, shiftKey) {
    window.dispatchEvent(new KeyboardEvent("keydown", {
      key,
      code: code || "",
      shiftKey: !!shiftKey,
      bubbles: true,
      cancelable: true
    }));
  }

  input.addEventListener("compositionstart", () => { composing = true; });
  input.addEventListener("compositionend", (e) => {
    composing = false;
    const value = e.data || "";
    for (const ch of value) forwardKey(ch, "", false);
    input.value = "";
  });

  input.addEventListener("input", (e) => {
    if (composing) return;
    const value = input.value;
    if (!value) return;

    for (const ch of value) {
      if (ch === "\n") forwardKey("Enter", "Enter", false);
      else forwardKey(ch, "", false);
    }
    input.value = "";
  });

  input.addEventListener("keydown", (e) => {
    if (e.key === "Backspace" || e.key === "Tab" || e.key === "Enter") {
      e.preventDefault();
      forwardKey(e.key, e.code, e.shiftKey);
      input.value = "";
    }
  });

  // Give the mobile keyboard a real focus target when the user touches
  // the typing/practice area, without changing the desktop keyboard behavior.
  document.addEventListener("touchstart", (e) => {
    const el = e.target;
    if (el && el.closest && (
      el.closest("main") ||
      el.closest("[contenteditable='true']")
    )) {
      setTimeout(focusNativeKeyboard, 0);
    }
  }, { passive: true });

  window.addEventListener("orientationchange", () => {
    setTimeout(() => {
      if (document.activeElement === input) focusNativeKeyboard();
    }, 150);
  });
})();

